using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeQueryValidatorTests{[Fact]public void Null_queries_are_rejected(){var v=KnowledgeQueryFixture.Validator();Assert.Throws<ArgumentNullException>(()=>v.Validate((AstronomyKnowledgeCatalogQuery)null!));Assert.Throws<ArgumentNullException>(()=>v.Validate((AstronomyKnowledgeStatementQuery)null!));}[Fact]public void Valid_queries_pass(){var t=KnowledgeQueryFixture.RealTypeId();Assert.True(KnowledgeQueryFixture.Validator().Validate(new AstronomyKnowledgeCatalogQuery(knowledgeTypes:new([t]))).IsValid);Assert.True(KnowledgeQueryFixture.Validator().Validate(new AstronomyKnowledgeStatementQuery(knowledgeTypes:new([t]))).IsValid);}[Fact]public void Unknown_and_conflicting_type_filters_are_reported_stably(){var real=KnowledgeQueryFixture.Catalog().Snapshot.KnowledgeTypes[0];var wrongDomain=Enum.GetValues<AstronomyKnowledgeDomain>().First(d=>d!=real.Domain!.Value);var q=new AstronomyKnowledgeCatalogQuery(domains:new([wrongDomain]),families:new([Enum.GetValues<AstronomyKnowledgePayloadFamily>().First(f=>f!=real.Family!.Value)]),knowledgeTypes:new([real.KnowledgeTypeId!.Value, AstronomyKnowledgeTypeId.Create("unknown-type") ]));var issues=KnowledgeQueryFixture.Validator().Validate(q).Issues;Assert.Equal(AstronomyKnowledgeQueryValidationCode.DomainKnowledgeTypeConflict,issues[0].Code);Assert.Equal("$.knowledgeTypes",issues[0].Path);Assert.Equal(AstronomyKnowledgeQueryTarget.CatalogEntry,issues[0].Target);Assert.Equal(AstronomyKnowledgeQueryValidationCode.FamilyKnowledgeTypeConflict,issues[1].Code);Assert.Equal(AstronomyKnowledgeQueryValidationCode.UnknownKnowledgeType,issues[2].Code);}[Fact]public void Repeated_validation_is_stable_and_does_not_mutate(){var q=new AstronomyKnowledgeStatementQuery(statementKinds:new([Astronomy.MediaFactory.Core.KnowledgeFoundation.KnowledgeStatementKind.Scientific,Astronomy.MediaFactory.Core.KnowledgeFoundation.KnowledgeStatementKind.Visual],AstronomyKnowledgeQueryMatchMode.All));var a=KnowledgeQueryFixture.Validator().Validate(q).Issues;var b=KnowledgeQueryFixture.Validator().Validate(q).Issues;Assert.Equal(a.Select(i=>i.Code),b.Select(i=>i.Code));Assert.Equal(2,q.StatementKinds!.Values.Count);}}
